/**
 * A deliberately neutral last resort. It is preferable to an unrelated
 * destination photograph while a package is waiting for its verified media
 * set. Package cards and detail pages must never fall back to the old scraped
 * image pool.
 */
export const PACKAGE_MEDIA_PLACEHOLDER = "/images/hero/hero-bg-2.svg";

type PackageMediaInput = {
  slug: string;
  title?: string;
  route?: string;
  category?: string;
};

const LOCATION_STOP_WORDS = new Set([
  "india", "indian", "tour", "tours", "package", "packages", "trip", "trips",
  "travel", "holiday", "holidays", "yatra", "city", "state", "island", "islands",
]);

// The inventory's first file is not automatically its best card crop. Keep
// rare, human-reviewed choices here rather than replacing an image with a
// loosely related stock photo. This fixes the former Manali truck/climber
// treatment with a clean MQT-branded Himalayan vista from the same location.
const PREFERRED_HERO_IMAGES: Record<string, string> = {
  "/images/location-library/manali-himachal-pradesh-india/manali-himachal-pradesh-india-01-lg.webp": "/images/location-library/manali-himachal-pradesh-india/manali-himachal-pradesh-india-03-lg.webp",
};

function locationTokens(value: string) {
  return value
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((token) => token.length > 2 && !LOCATION_STOP_WORDS.has(token));
}

function withPreferredHero(media: PackageLocationMedia): PackageLocationMedia {
  const preferred = PREFERRED_HERO_IMAGES[media.primary];
  if (!preferred) return media;

  const hero = media.gallery.find((item) => item.src === preferred);
  if (!hero) return media;
  return {
    ...media,
    primary: preferred,
    gallery: [hero, ...media.gallery.filter((item) => item.src !== preferred)],
  };
}

/**
 * Returns only media which has been matched to a real location in the supplied
 * image inventory. Exact package assignments win. For legacy package records
 * that were not included in the initial exact pass, use a conservative
 * location-name match against their title and route. This lets a Himachal or
 * Manali package inherit the verified Himachal/Manali set without ever falling
 * back to a random image from /images/packages.
 */
export function getPackageLocationMedia(input: PackageMediaInput): PackageLocationMedia | undefined {
  const exact = packageLocationMedia[input.slug];
  if (exact) return withPreferredHero(exact);

  const sourceTokens = new Set(locationTokens(`${input.title || ""} ${input.route || ""} ${input.slug}`));
  if (sourceTokens.size === 0) return undefined;

  let best: { media: PackageLocationMedia; score: number } | undefined;
  const seen = new Set<string>();

  for (const media of Object.values(packageLocationMedia)) {
    // Several packages share a media record. Inspect each unique record once.
    if (seen.has(media.primary)) continue;
    seen.add(media.primary);

    for (const location of media.locations) {
      const tokens = locationTokens(location);
      // A one-word match such as "Goa" is still meaningful, but very short
      // terms are too easy to match accidentally in package titles.
      if (tokens.length === 0 || (tokens.length === 1 && tokens[0].length < 4)) continue;
      if (!tokens.every((token) => sourceTokens.has(token))) continue;

      const score = tokens.length * 100 + location.length;
      if (!best || score > best.score) best = { media, score };
    }
  }

  return best ? withPreferredHero(best.media) : undefined;
}

export function getApprovedPackageImage(input: PackageMediaInput): string {
  return getPackageLocationMedia(input)?.primary || PACKAGE_MEDIA_PLACEHOLDER;
}
